@cached_property
def click_methods(self):
    return {
        'ADB': self.click_adb,
        'uiautomator2': self.click_uiautomator2,
        'minitouch': self.click_minitouch,
        'scrcpy': self.click_scrcpy,
        'Hermit': self.click_hermit,
        'MaaTouch': self.click_maatouch,
        'nemu_ipc': self.click_nemu_ipc,
    }

def long_click(self, button, duration=(1, 1.2)):
    """Method to long click a button.

    Args:
        button (button.Button): AzurLane Button instance.
        duration(int, float, tuple):
    """
    self.handle_control_check(button)
    x, y = random_rectangle_point(button.button)
    x, y = ensure_int(x, y)
    duration = ensure_time(duration)
    logger.info(
        'Click %s @ %s, %s' % (point2str(x, y), button, duration)
    )
    if isinstance(button, HierarchyButton):
        self.swipe_adb((x, y), (x, y), duration, native=True)
        return
    method = self.config.Emulator_ControlMethod
    if method == 'minitouch':
        self.long_click_minitouch(x, y, duration)
    elif method == 'uiautomator2':
        self.long_click_uiautomator2(x, y, duration)
    elif method == 'scrcpy':
        self.long_click_scrcpy(x, y, duration)
    elif method == 'MaaTouch':
        self.long_click_maatouch(x, y, duration)
    elif method == 'nemu_ipc':
        self.long_click_nemu_ipc(x, y, duration)
    else:
        self.swipe_adb((x, y), (x, y), duration)

@retry
def click_adb(self, x, y, native=False):
    if not native:
        x, y = self.control_point(x, y)
    start = time.time()
    self.adb_shell(['input', 'tap', x, y])
    if time.time() - start <= 0.05:
        self.sleep(0.05)

@retry
def swipe_adb(self, p1, p2, duration=0.1, native=False):
    if not native:
        p1, p2 = self.control_point(*p1), self.control_point(*p2)
    duration = int(duration * 1000)
    self.adb_shell(['input', 'swipe', *p1, *p2, duration])

@retry
def screenshot_droidcast(self):
    self.config.DROIDCAST_VERSION = 'DroidCast'
    if self.is_mumu_over_version_356:
        if not self.droidcast_width or not self.droidcast_height:
            self._droidcast_update_resolution()

    resp = self.droidcast_session.get(self.droidcast_url(), timeout=3)

    if resp.status_code == 404:
        raise DroidCastVersionIncompatible('DroidCast server does not have /preview')
    image = resp.content
    image = np.frombuffer(image, np.uint8)
    if image is None:
        raise ImageTruncated('Empty image after reading from buffer')
    if image.size in [w * h * 2 for w, h in SUPPORTED_SCREEN_SIZES]:
        raise DroidCastVersionIncompatible('Requesting screenshots from `DroidCast` but server is `DroidCast_raw`')
    if image.size < 500:
        logger.warning(f'Unexpected screenshot: {resp.content}')

    image = cv2.imdecode(image, cv2.IMREAD_COLOR)
    if image is None:
        raise ImageTruncated('Empty image after cv2.imdecode')

    cv2.cvtColor(image, cv2.COLOR_BGR2RGB, dst=image)
    if image is None:
        raise ImageTruncated('Empty image after cv2.cvtColor')

    if self.is_mumu_over_version_356:
        if self.orientation == 1:
            image = cv2.rotate(image, cv2.ROTATE_90_CLOCKWISE)

    return image

@retry
def click_hermit(self, x, y):
    x, y = self.control_point(x, y)
    self.hermit_send('/click', x=x, y=y)

@property
def normalized_coordinates(self):
    # MaaTouch always consumes the pixel range from its handshake, even
    # when ADB is being accessed through an HTTP uiautomator2 connection.
    return False

@property
def normalized_coordinates(self):
    # atx-agent expects fractions of the display, not physical pixels.
    return self.device.config.DEVICE_OVER_HTTP

def convert(self, x, y):
    max_x, max_y = self.device.max_x, self.device.max_y
    orientation = self.orientation

    if orientation == 0:
        pass
    elif orientation == 1:
        x, y = 720 - y, x
        max_x, max_y = max_y, max_x
    elif orientation == 2:
        x, y = 1280 - x, 720 - y
    elif orientation == 3:
        x, y = y, 1280 - x
        max_x, max_y = max_y, max_x
    else:
        raise ScriptError(f'Invalid device orientation: {orientation}')

    self.max_x, self.max_y = max_x, max_y
    if not self.normalized_coordinates:
        # Maximum X and Y coordinates may, but usually do not, match the display size.
        x, y = int(x / 1280 * max_x), int(y / 720 * max_y)
    else:
        # When over http, max_x and max_y are default to 1280 and 720, skip matching display size
        x, y = int(x), int(y)
    return x, y

def _control_point(self, x, y):
    source = ASSET_SIZE
    if self.resolution[0] < self.resolution[1]:
        # Screenshot normalizes portrait frames after rotating them. Input
        # coordinates must undo that rotation in the stream's coordinate space.
        orientation = self.parent.orientation
        if orientation == 1:
            x, y = ASSET_SIZE[1] - y, x
            source = ASSET_SIZE[::-1]
        elif orientation == 3:
            x, y = y, ASSET_SIZE[0] - x
            source = ASSET_SIZE[::-1]
    x, y = scale_point(x, y, source, self.resolution)
    return (max(0, min(int(x), self.resolution[0] - 1)),
            max(0, min(int(y), self.resolution[1] - 1)))

@retry
def click_uiautomator2(self, x, y):
    x, y = self.control_point(x, y)
    self.u2.click(x, y)

@retry
def long_click_uiautomator2(self, x, y, duration=(1, 1.2)):
    x, y = self.control_point(x, y)
    self.u2.long_click(x, y, duration=duration)

@retry
def swipe_uiautomator2(self, p1, p2, duration=0.1):
    p1, p2 = self.control_point(*p1), self.control_point(*p2)
    self.u2.swipe(*p1, *p2, duration=duration)

def _handle_orientated_image(self, image):
    """
    Args:
        image (np.ndarray):

    Returns:
        np.ndarray:
    """
    width, height = image_size(image)
    if (width, height) in SUPPORTED_SCREEN_SIZES:
        return image

    # Several backends already return landscape pixels on portrait devices.
    # Rotating those again would turn a valid 1440P frame on its side.
    if self.orientation == 0:
        pass
    elif self.orientation == 1:
        image = cv2.rotate(image, cv2.ROTATE_90_COUNTERCLOCKWISE)
    elif self.orientation == 2:
        image = cv2.rotate(image, cv2.ROTATE_180)
    elif self.orientation == 3:
        image = cv2.rotate(image, cv2.ROTATE_90_CLOCKWISE)
    else:
        raise ScriptError(f'Invalid device orientation: {self.orientation}')

    return image

def check_screen_black(self):
    if self._screen_black_checked:
        return True
    # Check screen color
    # May get a pure black screenshot on some emulators.
    color = get_color(self.image, area=(0, 0, *ASSET_SIZE))
    if sum(color) < 1:
        if self.config.Emulator_Serial == 'wsa-0':
            for _ in range(2):
                display = self.get_display_id()
                if display == 0:
                    return True
            logger.info(f'Game running on display {display}')
            logger.warning('Game not running on display 0, will be restarted')
            self.app_stop_uiautomator2()
            return False
        elif self.config.Emulator_ScreenshotMethod == 'uiautomator2':
            logger.warning(f'Received pure black screenshots from emulator, color: {color}')
            logger.warning('Uninstall minicap and retry')
            self.uninstall_minicap()
            self._screen_black_checked = False
            return False
        else:
            logger.warning(f'Received pure black screenshots from emulator, color: {color}')
            logger.warning(f'Screenshot method `{self.config.Emulator_ScreenshotMethod}` '
                           f'may not work on emulator `{self.serial}`, or the emulator is not fully started')
            if self.is_mumu_family:
                if self.config.Emulator_ScreenshotMethod == 'DroidCast':
                    self.droidcast_stop()
                else:
                    logger.warning('If you are using MuMu X, please upgrade to version >= 12.1.5.0')
            self._screen_black_checked = False
            return False
    else:
        self._screen_black_checked = True
        return True

def get_for_any_ele(self, list_u2_path: list) -> Union[bool, tuple]:
    """
    Args:
        list_u2_path (list): [UiObject or XPathSelector]  In this case, len(list_u2_path) >= 1
    Returns:
        bool: False if wait failed
        tuple: (bounds): if wait success
    """
    for path in list_u2_path:
        try:
            if isinstance(path, UiObject):
                if path.exists():
                    return self.device.logical_area(path.bounds())
                elif not path.exists():
                    continue
            elif isinstance(path, XPathSelector):
                if path.exists:
                    return self.device.logical_area(path.bounds)
                elif not path.exists:
                    continue
        except XPathElementNotFoundError:
            continue
    return False
